package main

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"
)

const goHeader = "// Code generated by cmd/gen from contracts/enums.json. DO NOT EDIT.\n\n"

// output is one generated file: path relative to its root and its content.
type output struct {
	Path string
	Data []byte
}

func formatGo(path string, src bytes.Buffer) (output, error) {
	out, err := format.Source(src.Bytes())
	if err != nil {
		return output{}, fmt.Errorf("%s: generated code does not parse: %w", path, err)
	}
	return output{Path: path, Data: out}, nil
}

// goConst is the Go identifier of an enum value, e.g. RoleSuperAdmin.
func goConst(enumName, value string) string { return enumName + pascal(value) }

func emitEnums(c *Contract) (output, error) {
	var b bytes.Buffer
	b.WriteString(goHeader + "package enum\n")
	seen := map[string]string{}
	for _, name := range sortedKeys(c.Enums) {
		values := c.Enums[name]
		fmt.Fprintf(&b, "\ntype %s string\n\nconst (\n", name)
		consts := make([]string, len(values))
		for i, v := range values {
			id := goConst(name, v)
			if prev, ok := seen[id]; ok {
				return output{}, fmt.Errorf("enum: %s and %s.%s both generate %s", prev, name, v, id)
			}
			seen[id] = name + "." + v
			consts[i] = id
			fmt.Fprintf(&b, "\t%s %s = %q\n", id, name, v)
		}
		fmt.Fprintf(&b, ")\n\n// %sValues returns every %s in contract order.\n", name, name)
		fmt.Fprintf(&b, "func %sValues() []%s { return []%s{%s} }\n", name, name, name, strings.Join(consts, ", "))
		fmt.Fprintf(&b, "\n// Valid reports whether v is a contract value. Use it on every value read from outside.\n")
		fmt.Fprintf(&b, "func (v %s) Valid() bool {\n\tswitch v {\n\tcase %s:\n\t\treturn true\n\t}\n\treturn false\n}\n", name, strings.Join(consts, ", "))
	}
	return formatGo("internal/shared/enum/enum_gen.go", b)
}

func emitPermissions(c *Contract) (output, error) {
	var b bytes.Buffer
	b.WriteString(goHeader + "package authz\n\nimport \"gp/internal/shared/enum\"\n\n")
	b.WriteString("var rolePermissions = map[enum.Role]map[enum.Permission]bool{\n")
	for _, role := range c.Enums["Role"] {
		fmt.Fprintf(&b, "\tenum.%s: {\n", goConst("Role", role))
		for _, p := range c.RolePermissions[role] {
			fmt.Fprintf(&b, "\t\tenum.%s: true,\n", goConst("Permission", p))
		}
		b.WriteString("\t},\n")
	}
	b.WriteString("}\n\n")
	b.WriteString("// conditionalPermissions holds permissions a role has only when a membership\n")
	b.WriteString("// condition is true. The text is the condition, evaluated by Require.\n")
	b.WriteString("var conditionalPermissions = map[enum.Role]map[enum.Permission]string{\n")
	for _, role := range c.Enums["Role"] {
		conds, ok := c.ConditionalPermissions[role]
		if !ok {
			continue
		}
		fmt.Fprintf(&b, "\tenum.%s: {\n", goConst("Role", role))
		for _, p := range c.Enums["Permission"] {
			if cond, ok := conds[p]; ok {
				fmt.Fprintf(&b, "\t\tenum.%s: %s,\n", goConst("Permission", p), strconv.Quote(cond))
			}
		}
		b.WriteString("\t},\n")
	}
	b.WriteString("}\n\n")
	b.WriteString(`// RoleHas reports whether the role holds the permission without any condition.
func RoleHas(r enum.Role, p enum.Permission) bool { return rolePermissions[r][p] }

// Condition returns the membership condition a role needs for a permission, if any.
func Condition(r enum.Role, p enum.Permission) (string, bool) {
	cond, ok := conditionalPermissions[r][p]
	return cond, ok
}
`)
	return formatGo("internal/shared/authz/perm_gen.go", b)
}

func emitFlow(c *Contract) (output, error) {
	var b bytes.Buffer
	b.WriteString(goHeader + "package order\n\nimport (\n\t\"slices\"\n\n\t\"gp/internal/shared/enum\"\n)\n\n")
	b.WriteString(`// Transition is one allowed order status move (docs/03-order-flow.md).
type Transition struct {
	ID string
	// From is empty only for the first state (T01).
	From           enum.OrderStatus
	To             enum.OrderStatus
	ReasonRequired bool
	actors         []string
}

// AllowedFor reports whether the actor may make this move. The actor is a Role
// value or "SYSTEM" (timers and webhooks), which is not a Role.
func (t Transition) AllowedFor(actor string) bool { return slices.Contains(t.actors, actor) }

var transitions = []Transition{
`)
	for _, t := range c.OrderTransitions {
		from := ""
		if t.From != nil {
			from = *t.From
		}
		actors := make([]string, len(t.Actors))
		for i, a := range t.Actors {
			actors[i] = strconv.Quote(a)
		}
		fmt.Fprintf(&b, "\t{ID: %q, From: %s, To: %s, ReasonRequired: %t, actors: []string{%s}},\n",
			t.ID, statusConst(from), statusConst(t.To), t.Reason, strings.Join(actors, ", "))
	}
	b.WriteString("}\n\n")
	b.WriteString(`// Transitions returns every allowed move.
func Transitions() []Transition { return slices.Clone(transitions) }

// Lookup finds the move between two statuses.
func Lookup(from, to enum.OrderStatus) (Transition, bool) {
	for _, t := range transitions {
		if t.From == from && t.To == to {
			return t, true
		}
	}
	return Transition{}, false
}

// Allowed reports whether actor may move an order from one status to another.
func Allowed(from, to enum.OrderStatus, actor string) bool {
	t, ok := Lookup(from, to)
	return ok && t.AllowedFor(actor)
}

// IsFinal reports whether no further move is possible.
func IsFinal(s enum.OrderStatus) bool {
	switch s {
`)
	finals := make([]string, len(c.FinalOrderStatuses))
	for i, s := range c.FinalOrderStatuses {
		finals[i] = statusConst(s)
	}
	sort.Strings(finals)
	fmt.Fprintf(&b, "\tcase %s:\n\t\treturn true\n\t}\n\treturn false\n}\n", strings.Join(finals, ", "))
	return formatGo("internal/order/flow_gen.go", b)
}

func statusConst(status string) string {
	if status == "" {
		return `""`
	}
	return "enum." + goConst("OrderStatus", status)
}

func emitErrorCodes(c *Contract) (output, error) {
	var b bytes.Buffer
	b.WriteString(goHeader + "package apperr\n\n// Code is a stable error code from the contract. Clients switch on it.\ntype Code string\n\nconst (\n")
	names := sortedKeys(c.ErrorCodes)
	ids := make([]string, len(names))
	for i, n := range names {
		ids[i] = pascal(n) // apperr.SlotFull, as written in docs/07 §2
		fmt.Fprintf(&b, "\t%s Code = %q\n", ids[i], n)
	}
	b.WriteString(")\n\n// Codes returns every contract error code, sorted by name.\n")
	fmt.Fprintf(&b, "func Codes() []Code { return []Code{%s} }\n\n", strings.Join(ids, ", "))
	b.WriteString("// Valid reports whether c is a contract code.\nfunc (c Code) Valid() bool {\n\tswitch c {\n")
	fmt.Fprintf(&b, "\tcase %s:\n\t\treturn true\n\t}\n\treturn false\n}\n\n", strings.Join(ids, ", "))
	b.WriteString("// HTTPStatus is the response status for the code; unknown codes map to 500.\nfunc (c Code) HTTPStatus() int {\n\tswitch c {\n")
	for i, n := range names {
		fmt.Fprintf(&b, "\tcase %s:\n\t\treturn %d\n", ids[i], c.ErrorCodes[n].HTTP)
	}
	b.WriteString("\t}\n\treturn 500\n}\n\n")
	b.WriteString("// Message is the text shown to the user; unknown codes get the INTERNAL text.\nfunc (c Code) Message() string {\n\tswitch c {\n")
	for i, n := range names {
		fmt.Fprintf(&b, "\tcase %s:\n\t\treturn %s\n", ids[i], strconv.Quote(c.ErrorCodes[n].Message))
	}
	fmt.Fprintf(&b, "\t}\n\treturn %s\n}\n", strconv.Quote(c.ErrorCodes["INTERNAL"].Message))
	return formatGo("internal/shared/apperr/codes_gen.go", b)
}
